CREATE COLUMN TABLE "TEST_AP"."OSRT" ("AbsId" INTEGER CS_INT NOT NULL , "SumRptId" NVARCHAR(100) NOT NULL , "SumRptDate" LONGDATE CS_LONGDATE, "BPLId" INTEGER CS_INT, "FromDate" LONGDATE CS_LONGDATE, "ToDate" LONGDATE CS_LONGDATE, "RptType" NVARCHAR(1) DEFAULT 'C', "version" NVARCHAR(50), "SumSubId" NVARCHAR(254), "SumRptType" NVARCHAR(254), PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OSRT_SUM_RPT_ID" ON "TEST_AP"."OSRT" ( "SumRptId" ASC )